func (b *BeaconState) HashTreeRoot(ctx context.Context) ([32]byte, error) {
    b.lock.Lock()
    defer b.lock.Unlock()
    if err := b.initializeMerkleLayers(ctx); err != nil {
        return [32]byte{}, err
    }
    if err := b.recomputeDirtyFields(ctx); err != nil {
        return [32]byte{}, err
    }
    return bytesutil.ToBytes32(b.merkleLayers[len(b.merkleLayers)-1][0]), nil
}

func (b *BeaconState) initializeMerkleLayers(ctx context.Context) error {
    if len(b.merkleLayers) > 0 {
        return nil
    }
    fieldRoots, err := ComputeFieldRootsWithHasher(ctx, b)
    if err != nil {
        return err
    }
    layers := stateutil.Merkleize(fieldRoots)
    b.merkleLayers = layers
    return nil
}

// recomputeDirtyFields iterates over Go map with non-deterministic order:
func (b *BeaconState) recomputeDirtyFields(ctx context.Context) error {
    for field := range b.dirtyFields {  // map iteration - non-deterministic order
        root, err := b.rootSelector(ctx, field)
        idx := field.RealPosition()    // fixed compile-time position - determinism preserved
        b.merkleLayers[0][idx] = root[:]
        b.recomputeRoot(idx)
        delete(b.dirtyFields, field)
    }
    return nil
}

// The actual implementation is in stateutil.Merkleize (beacon-chain/state/stateutil/trie_helpers.go)
func Merkleize(leaves [][]byte) [][][]byte {
    hashFunc := hash.CustomSHA256Hasher()
    layers := make([][][]byte, ssz.Depth(uint64(len(leaves)))+1)  // BUG: depth computed BEFORE padding
    for len(leaves)%32 != 0 {
        leaves = append(leaves, make([]byte, 32))  // padding AFTER allocation
    }
    currentLayer := leaves
    layers[0] = currentLayer

    i := 1
    for len(currentLayer) > 1 && i < len(layers) {  // terminates prematurely when layers is undersized
        layer := make([][]byte, 0)
        for i := 0; i < len(currentLayer); i += 2 {  // inner i shadows outer i
            hashedChunk := hashFunc(append(currentLayer[i], currentLayer[i+1]...))
            layer = append(layer, hashedChunk[:])
        }
        currentLayer = layer
        layers[i] = currentLayer
        i++
    }
    return layers
}

